import jax
import jax.numpy as jnp

@jax.experimental.custom_dce.custom_dce
def f(x, y):
    return jnp.sin(x) * y, x * jnp.sin(y)

@f.def_dce
def f_dce_rule(used_outs, x, y):
    return (
        jnp.sin(x) * y if used_outs[0] else None,
        x * jnp.sin(y) if used_outs[1] else None,
    )
